import sys
sys.setrecursionlimit(10**7)

def main():
    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    L = [0] * n
    C = [0] * n
    for i in range(n):
        L[i] = int(next(it))
    for i in range(n):
        C[i] = int(next(it))
    adj = [[] for _ in range(n)]
    for _ in range(n - 1):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)

    sorted_L = sorted(L)
    T = sorted_L[n // 2]

    f = [0] * n
    ans = [0] * n

    def dfs1(u, p):
        f[u] = C[u]
        for v in adj[u]:
            if v == p:
                continue
            dfs1(v, u)
            f[u] += min(0, f[v])

    def dfs2(u, p):
        if p == -1:
            ans[u] = f[u]
        for v in adj[u]:
            if v == p:
                continue
            without_v = ans[u] - min(0, f[v])
            res = C[v]
            for w in adj[v]:
                if w == u:
                    continue
                res += min(0, f[w])
            res += min(0, without_v)
            ans[v] = res
            dfs2(v, u)

    dfs1(0, -1)
    dfs2(0, -1)

    total = 0
    for i in range(n):
        total += abs(L[i] - T) * ans[i]
    print(total)

if __name__ == "__main__":
    main()
